// === Tab: mySketch ===
const blackholes=[]
const stars=[]
const starsNum=5e3
const blackholesNum=24
const blackholeShiftInterval=60
const speed=3

randomXY=()=>
  createVector(
    random(width),
    random(height)
  )

setup=()=>{
  createCanvas(800,800)
  for(let i=starsNum;i--;)
    stars.push(randomXY())  
  for(let i=blackholesNum;i--;)
    blackholes.push(randomXY())
}

draw=()=> {
  background('black')
  stroke('white')  
  if(frameCount%blackholeShiftInterval==0){
    blackholes.shift()
    blackholes.push(randomXY())
  }  
  for(const s of stars){
    let direction=0 
    for(const b of blackholes){
      const dx=s.x-b.x
      const dy=s.y-b.y
      if(dx**2+dy**2>1)
        direction+=atan2(dy,dx) // Simply add up the angles with each blackhole
      else{ //if a star arrives at a blackhole
        const angle=random(TWO_PI)
        s.x=width/2+cos(angle)*width/3
        s.y=height/2+sin(angle)*height/3
        direction=0
        break;
      }
    }
    line(s.x,s.y,s.x+=cos(direction)*speed,s.y+=sin(direction)*speed)
  }
}
